"use client";

import { Card } from "@/components/ui/card";
import { useEffect, useState } from "react";

const banners = [
  {
    id: 1,
    title: "Welcome to Our Event!",
    description: "Don't miss the excitement 🎉",
    imageUrl: "/banner1.jpg",
  },
  {
    id: 2,
    title: "Exclusive Deals",
    description: "Get your ticket now!",
    imageUrl: "/banner2.jpg",
  },
];

export default function Banner() {
  const [index, setIndex] = useState(0);

  useEffect(() => {
    const timer = setInterval(() => {
      setIndex((prev) => (prev + 1) % banners.length);
    }, 3000);
    return () => clearInterval(timer);
  }, []);

  const currentBanner = banners[index];

  return (
    <Card className="w-full h-64 relative overflow-hidden">
      <img
        src={currentBanner.imageUrl}
        alt={currentBanner.title}
        className="w-full h-full object-cover absolute inset-0"
      />
      <div className="absolute bottom-0 bg-black/50 text-white p-4 w-full">
        <h2 className="text-xl font-bold">{currentBanner.title}</h2>
        <p>{currentBanner.description}</p>
      </div>
    </Card>
  );
}
